int main() {
    string input;
    while (getline(cin, input)) {
        // 跳过空字符串
        if (input.empty()) {
            continue;
        }
        // 不断切割为8个的字符串
        while (input.size() >= 8) {
            string tmp = input.substr(0, 8);
            cout << tmp<<endl;
            input = input.substr(8);
        }
        // 收尾，不是空字符串的补零
        if (!input.empty()) {
            input.append(8 - input.size(), '0');
            cout << input << endl;
        }
    }
​
    return 0;
}

