package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    for scanner.Scan() {
        input := strings.TrimSpace(scanner.Text())
        // 跳过空字符串
        if len(input) == 0 {
            continue
        }
​
        // 不断切割为8个字符的子串
        for len(input) >= 8 {
            fmt.Println(input[:8])
            input = input[8:]
        }
​
        // 收尾，不是空字符串的补零
        if len(input) > 0 {
            fmt.Println(input + strings.Repeat("0", 8-len(input)))
        }
    }
}
